#!/usr/bin/env python3
"""The private Steam engine map in a publication job (Korri ADR 0083).

The published @korri:steam carries the engine map compiled into its engine
host; the map itself is in no repository. It comes from the Actions secret
STEAM_ENGINE_MAP_TGZ_B64: base64 of `tar czf` of the map folder: one
engine.map per system, `aarch64-linux/engine.map` and
`x86_64-linux/engine.map`, as in plugins/steam/engine-host/map.

  steam-engine-map.py setup
      With the secret: unpack the map into $RUNNER_TEMP/steam-engine-map
      (mode 0700, file 0600), outside the checkout, and put a `nix` shim first
      on PATH that adds `--override-input steam-engine-map path:<folder>` to
      every nix command on this flake (`.`/`.#…` installables). Without the
      secret (forks, pull requests): do nothing; the build uses the empty
      public map and the Steam host reports engine_map_missing.
  steam-engine-map.py check-closure PATHS_FILE
      Fail if the map's store path is in the runtime closure of the paths the
      job uploads. The compiled host holds the map's addresses by design; the
      map file itself must never be uploaded.
  steam-engine-map.py check-host SYSTEM PATHS_FILE
      Fail if the closure of the paths the job uploads holds a Steam engine
      host (packages.SYSTEM.korri-steam-host) other than the one the shim
      builds from the private map: a host from the empty public map, or any
      host when the job has no private map. A tool that runs its own nix
      bypasses the shim; this check sees the result, not the route.

Nothing here prints the secret, the map or any line of it.
"""
import base64
import io
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import tarfile

SECRET = "STEAM_ENGINE_MAP_TGZ_B64"
INPUT = "steam-engine-map"
# The archive's files: one map per system the engine host is published for.
SYSTEMS = ("aarch64-linux", "x86_64-linux")
MAPS = tuple(f"{system}/engine.map" for system in SYSTEMS)
MAX_MAP = 1 << 20

SHIM = """#!{bash}
# Generated by steam-engine-map.py: every nix command on this flake builds the
# Steam engine host from the private map. Other commands pass through.
real={real}
map={map}
local_flake() {{
  local arg
  for arg in "$@"; do
    case "$arg" in .|.#*|./|./#*) return 0 ;; esac
  done
  return 1
}}
if local_flake "$@"; then
  case "$1" in
    build|eval|run|shell|develop|path-info|derivation|why-depends|print-dev-env)
      exec "$real" "$1" --override-input {input} "path:$map" "${{@:2}}" ;;
    flake)
      case "${{2:-}}" in
        check|show|metadata|archive)
          exec "$real" flake "$2" --override-input {input} "path:$map" "${{@:3}}" ;;
      esac ;;
  esac
fi
exec "$real" "$@"
"""


def fail(message):
    print(f"steam-engine-map: {message}", file=sys.stderr)
    sys.exit(1)


def unpack(encoded: str, folder: Path):
    """The secret's files, <system>/engine.map for each system, into `folder`;
    no other file. Folder entries of the two systems may be present."""
    try:
        raw = base64.b64decode(encoded.strip(), validate=True)
        archive = tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz")
        members = {m.name.removeprefix("./").rstrip("/"): m for m in archive.getmembers()}
    except Exception:
        fail(f"{SECRET} is not base64 of a gzip tar")
    members.pop("", None)
    members.pop(".", None)
    for system in SYSTEMS:
        if system in members and members[system].isdir():
            del members[system]
    wrong = sorted(members) != sorted(MAPS) or any(
        not m.isfile() or m.size > MAX_MAP for m in members.values())
    if wrong:
        fail(f"{SECRET} must hold exactly the regular files {' and '.join(MAPS)}")
    maps = {}
    for name in MAPS:
        data = archive.extractfile(members[name]).read()
        lines = [l.strip() for l in data.decode("utf-8", "replace").splitlines()]
        if "format korri-steam-engine-map 1" not in lines or "status pass" not in lines:
            fail(f"{SECRET}: {name} is no remap map with status pass")
        maps[name] = data
    folder.mkdir(mode=0o700)
    os.chmod(folder, 0o700)
    for name, data in maps.items():
        target = folder / name
        target.parent.mkdir(mode=0o700)
        os.chmod(target.parent, 0o700)
        descriptor = os.open(target, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        with os.fdopen(descriptor, "wb") as stream:
            stream.write(data)


def setup(environ=os.environ):
    encoded = environ.get(SECRET, "")
    if not encoded.strip():
        print("steam-engine-map: no private map; the Steam host builds with the empty public map")
        return
    temp = Path(environ["RUNNER_TEMP"])
    folder = temp / "steam-engine-map"
    unpack(encoded, folder)
    real = environ.get("STEAM_ENGINE_REAL_NIX") or shutil.which("nix")
    if not real:
        fail("no nix on PATH")
    shim_bin = temp / "steam-engine-nix" / "bin"
    shim_bin.mkdir(parents=True)
    shim = shim_bin / "nix"
    shim.write_text(SHIM.format(
        bash=shutil.which("bash") or "/bin/bash", real=_quote(real),
        map=_quote(str(folder)), input=INPUT))
    shim.chmod(0o755)
    with open(environ["GITHUB_PATH"], "a") as stream:
        stream.write(f"{shim_bin}\n")
    with open(environ["GITHUB_ENV"], "a") as stream:
        stream.write(f"STEAM_ENGINE_MAP_DIR={folder}\n")
        stream.write(f"STEAM_ENGINE_REAL_NIX={real}\n")
    print("steam-engine-map: private map installed; nix commands on this flake use it")


def _quote(value: str) -> str:
    return "'" + value.replace("'", "'\\''") + "'"


MAP_COPY_NAME = "korri-steam-engine-map"


def map_store_path():
    """The store path Nix gives the overridden map input."""
    out = subprocess.check_output(["nix", "flake", "archive", "--dry-run", "--json", "."],
                                  text=True)
    return json.loads(out)["inputs"][INPUT]["path"]


def check_closure(paths_file: str, environ=os.environ):
    if not environ.get("STEAM_ENGINE_MAP_DIR"):
        print("steam-engine-map: no private map in this job")
        return
    map_path = map_store_path()
    paths = [p for p in Path(paths_file).read_text().split() if p]
    if not paths:
        return
    closure = subprocess.check_output(["nix", "path-info", "--recursive", *paths], text=True)
    # The host build copies the map to its own store path (MAP_COPY_NAME,
    # plugins/steam/packages/engine-host.nix); refuse that copy too.
    if any(path == map_path or path.endswith("-" + MAP_COPY_NAME) for path in closure.split()):
        fail("the private engine map's store path is in the upload closure")
    print(f"steam-engine-map: the map's store path is not in the closure of {len(paths)} paths")


HOST = "korri-steam-host"


def host_attribute(nix, system, attribute):
    return subprocess.check_output(
        [nix, "eval", "--raw", f".#packages.{system}.{HOST}.{attribute}"], text=True).strip()


def check_host(system, paths_file, environ=os.environ):
    paths = [p for p in Path(paths_file).read_text().split() if p]
    if not paths:
        return
    # `nix` is the shim when the job has the private map.
    name = host_attribute("nix", system, "name")
    closure = subprocess.check_output(["nix", "path-info", "--recursive", *paths], text=True)
    # A store path's name follows its 32-character hash and a dash.
    hosts = {path for path in closure.split() if Path(path).name[33:] == name}
    if not hosts:
        print(f"steam-engine-map: no Steam engine host in the closure of {len(paths)} paths")
        return
    if not environ.get("STEAM_ENGINE_MAP_DIR"):
        fail(f"the upload closure holds {HOST} built from the empty public map "
             f"({' '.join(sorted(hosts))}); publish @korri:steam only with {SECRET}")
    private = host_attribute("nix", system, "outPath")
    public = host_attribute(environ["STEAM_ENGINE_REAL_NIX"], system, "outPath")
    if private == public:
        fail(f"the private map and the public map give the same {HOST}")
    wrong = sorted(hosts - {private})
    if wrong:
        kinds = ["the empty public map's" if path == public else "an unknown" for path in wrong]
        fail(f"the upload closure holds {HOST} {' '.join(wrong)} "
             f"({', '.join(kinds)}), not the private map's {private}")
    print(f"steam-engine-map: the upload closure's {HOST} is the private map's {private}")


def main(argv):
    if argv[1:] == ["setup"]:
        setup()
    elif len(argv) == 3 and argv[1] == "check-closure":
        check_closure(argv[2])
    elif len(argv) == 4 and argv[1] == "check-host":
        check_host(argv[2], argv[3])
    else:
        fail("usage: steam-engine-map.py setup | check-closure PATHS_FILE"
             " | check-host SYSTEM PATHS_FILE")


if __name__ == "__main__":
    main(sys.argv)
